1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioOutcome = {
13	  results: StepResult[];
14	};
15	
16	type Item = { type: string; cursed?: boolean; enchantment?: number };
17	
18	type Customer = { yearsWithMHPCO: number };
19	
20	/** The policy-scope context a quote is priced in: who is buying, and whether
21	 * this is their first contract or a follow-up. */
22	type Policy = { customer: Customer; isFollowUpContract: boolean };
23	
24	type Damage = { itemType: string; amount: number };
25	
26	type Incident = { cause: string; damages: Damage[] };
27	
28	type QuoteStep = { op: string; items: Item[] };
29	
30	type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: Step[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const SURCHARGED_ENCHANTMENT_THRESHOLD = 5;
45	const ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	/**
51	 * "All amounts are rounded to whole G in the MHPCO's favour." One rule, two
52	 * directions: the MHPCO collects premiums, so those round UP; it disburses
53	 * payouts, so those round DOWN. The pair is named rather than written as bare
54	 * Math.ceil / Math.floor at the call sites so that the shared rule — and the
55	 * fact that the two directions are the same rule, not two ad-hoc conveniences —
56	 * survives a reader who only ever sees one of them.
57	 *
58	 * WHERE these are applied is load-bearing and is decided at the call site, not
59	 * here. In particular the claim path rounds the amount claimed BEFORE it is
60	 * clamped against the cap, so that the cap arithmetic runs in whole gold;
61	 * rounding the returned payout instead would leave a fraction in the remaining
62	 * cap. Intermediates — the halved damage amount, the per-damage deductible
63	 * subtraction — stay fractional per the spec.
64	 */
65	const roundedInFavourOfMHPCO = {
66	  collected: Math.ceil,
67	  disbursed: Math.floor,
68	};
69	
70	const BASE_PREMIUMS: Record<string, number> = {
71	  sword: 100,
72	  amulet: 60,
73	  staff: 80,
74	  potion: 40,
75	  rune: 25,
76	  moonstone: 25,
77	};
78	
79	const INSURANCE_VALUES: Record<string, number> = {
80	  sword: 1000,
81	  amulet: 600,
82	  rune: 250,
83	};
84	
85	const DEDUCTIBLE_PER_DAMAGE = 100;
86	const HALVED_ENCHANTMENT_THRESHOLD = 8;
87	const HALVED_REIMBURSEMENT = 0.5;
88	const FULL_REIMBURSEMENT = 1;
89	const CAP_MULTIPLIER = 2;
90	
91	const ALIKE_BLOCK_SIZE = 3;
92	const ALIKE_BLOCK_PREMIUM = 60;
93	
94	type AlikeGroup = [type: string, count: number];
95	
96	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
97	  const countByType = new Map<string, number>();
98	
99	  for (const item of items) {
100	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
101	  }
102	
103	  return [...countByType];
104	};
105	
106	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
107	
108	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
109	
110	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
111	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
112	
113	  return count * basePremiumOfType(type);
114	};
115	
116	/**
117	 * The policy base premium: the sum of the item base premiums, with the
118	 * alike-block discount applied. Policy-scope modifiers are percentages OF
119	 * THIS amount — never of a total that already includes item surcharges.
120	 */
121	const policyBasePremiumOf = (items: Item[]): number =>
122	  groupAlikeItems(items)
123	    .map(basePremiumOfGroup)
124	    .reduce((total, groupPremium) => total + groupPremium, 0);
125	
126	/**
127	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
128	 * premium, independent of the policy base and of the alike-block discount.
129	 */
130	const isCursed = (item: Item): boolean => item.cursed === true;
131	
132	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
133	
134	const carriesEnchantmentSurcharge = (item: Item): boolean =>
135	  enchantmentOf(item) >= SURCHARGED_ENCHANTMENT_THRESHOLD;
136	
137	const itemSurchargeRateOf = (item: Item): number =>
138	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
139	  (carriesEnchantmentSurcharge(item) ? ENCHANTMENT_SURCHARGE : 0);
140	
141	const itemSurchargesOf = (items: Item[]): number =>
142	  items.reduce(
143	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
144	    0,
145	  );
146	
147	/**
148	 * Policy-scope modifiers: each is a percentage of the policy base premium.
149	 * Surcharges and discounts are netted into a single rate, so the policy base is
150	 * multiplied exactly once — this keeps the result free of the rounding drift
151	 * that separate discount and surcharge terms would introduce. The netted rate
152	 * (and hence the returned amount) is negative when the discounts outweigh the
153	 * surcharges.
154	 */
155	const isLongStanding = (customer: Customer): boolean =>
156	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
157	
158	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
159	  FIRST_INSURANCE_SURCHARGE -
160	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
161	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
162	
163	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
164	  policyBase * policyModifierRateOf(policy);
165	
166	const quotePremium = (items: Item[], policy: Policy): number => {
167	  const policyBase = policyBasePremiumOf(items);
168	  const premium =
169	    policyBase +
170	    itemSurchargesOf(items) +
171	    policyModifiersOn(policyBase, policy) +
172	    PROCESSING_FEE;
173	
174	  return roundedInFavourOfMHPCO.collected(premium);
175	};
176	
177	/**
178	 * Whether any step precedes this one. A quote is a follow-up contract when the
179	 * customer already holds one, and today every step is a quote — so "has a
180	 * predecessor" and "is a follow-up contract" coincide.
181	 *
182	 * They stop coinciding once claim steps exist: a claim at index 0 would make
183	 * the quote at index 1 look like a follow-up. At that point the caller must
184	 * count preceding QUOTE steps instead of asking this. The name is deliberately
185	 * about position, not contracts, so that the substitution is a visible change
186	 * at the call site rather than a silent redefinition here.
187	 */
188	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
189	
190	const insuranceSumOf = (items: Item[]): number =>
191	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
192	
193	const isReimbursedByHalf = (item: Item): boolean =>
194	  enchantmentOf(item) >= HALVED_ENCHANTMENT_THRESHOLD;
195	
196	/**
197	 * The share of a damage amount that is reimbursed, before the deductible.
198	 *
199	 * The specification's dragon-material rule ("damage to items made of dragon
200	 * material is fully reimbursed") is deliberately ABSENT here, and `Item` has no
201	 * `material` field. The rule is unobservable given the other rules:
202	 *
203	 * - Full reimbursement is already FULL_REIMBURSEMENT, the default rate, so on
204	 *   items below the halving threshold a dragon clause would compute what this
205	 *   function computes anyway.
206	 * - The only inputs where the two clauses disagree are items with enchantment
207	 *   >= HALVED_ENCHANTMENT_THRESHOLD, and there the spec awards the conflict to
208	 *   halving ("both clauses apply; the 50 % rule wins").
209	 *
210	 * So no input distinguishes an implemented dragon clause from this one. The
211	 * spec's own examples confirm it: a steel sword and a dragon sword at
212	 * enchantment 9 with 1000 G damage both pay out 400 G. Implementing it would
213	 * add an unreachable branch and a field nothing reads.
214	 *
215	 * This stops holding the moment dragon material gains an effect OUTSIDE the
216	 * reimbursement rate — a different deductible, or an exemption from the payout
217	 * cap. Such a rule would need a real `material` field and a real branch.
218	 */
219	const reimbursementRateFor = (item: Item): number =>
220	  isReimbursedByHalf(item) ? HALVED_REIMBURSEMENT : FULL_REIMBURSEMENT;
221	
222	/**
223	 * The insured item a damage entry refers to. Shares the assumption documented
224	 * on `policyReferencedBy`: the damaged type is ASSUMED to be insured, and a
225	 * damage naming an uninsured or unknown type fails downstream with an opaque
226	 * undefined-property error rather than a rejection. The pending
227	 * error-handling tests are what will force a real rejection here.
228	 */
229	const insuredItemFor = (damage: Damage, items: Item[]): Item =>
230	  items.find(({ type }) => type === damage.itemType) as Item;
231	
232	/**
233	 * A single damage entry settles in two stages, in this order: the reimbursement
234	 * rate applies to the damage amount, and the deductible comes off the result.
235	 * The spec is explicit that the sequencing matters ("the 50 % rule wins, then
236	 * deductible"), so it is spelled out rather than left to operator precedence.
237	 */
238	const payoutForDamage = (damage: Damage, items: Item[]): number => {
239	  const reimbursed =
240	    damage.amount * reimbursementRateFor(insuredItemFor(damage, items));
241	
242	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
243	};
244	
245	/**
246	 * The quote step a claim is filed against. Today this ASSUMES the referenced
247	 * index holds a quote: nothing has forced the assumption to be checked yet, and
248	 * a claim naming a non-quote step fails here with an opaque undefined-property
249	 * error rather than a rejection.
250	 *
251	 * The assumption is isolated in this function on purpose. The pending
252	 * error-handling tests ("a claim for an item not part of the policy", "a claim
253	 * with a damage entry of an unknown item type") are what will force a real
254	 * rejection, and this is the single place that has to change when they do.
255	 */
256	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep =>
257	  steps[claim.policy] as QuoteStep;
258	
259	/**
260	 * The total a claim asks for: every damage entry settled on its own, then
261	 * summed. Unclamped — the payout cap is applied to this total, not per damage.
262	 */
263	const amountClaimed = (incident: Incident, items: Item[]): number =>
264	  incident.damages.reduce(
265	    (total, damage) => total + payoutForDamage(damage, items),
266	    0,
267	  );
268	
269	/**
270	 * Applying the payout cap to a claim: a policy pays at most what is left of its
271	 * cap, and whatever it pays comes off that remainder. Pure, and stated as a
272	 * before/after pair, so the invariant `payout + capAfter === capBefore` is
273	 * visible in one place rather than spread across the caller.
274	 */
275	const chargedAgainstCap = (claimed: number, capBefore: number): ClaimResult => {
276	  const payout = Math.min(claimed, capBefore);
277	
278	  return { payout, remainingCap: capBefore - payout };
279	};
280	
281	/**
282	 * The cap a policy starts with, before any claim has drawn on it.
283	 */
284	const initialCapOf = (policy: QuoteStep): number =>
285	  CAP_MULTIPLIER * insuranceSumOf(policy.items);
286	
287	/**
288	 * Settling a claim DRAWS DOWN the policy's remaining cap: the result depends on
289	 * how much earlier claims already consumed, so the running cap is read from and
290	 * written back to `capRemainingByPolicy`. That state write is this function's
291	 * one effect, and it is deliberately the last statement.
292	 */
293	const settleClaim = (
294	  claim: ClaimStep,
295	  steps: Step[],
296	  capRemainingByPolicy: Map<number, number>,
297	): ClaimResult => {
298	  const policy = policyReferencedBy(claim, steps);
299	  const capBefore =
300	    capRemainingByPolicy.get(claim.policy) ?? initialCapOf(policy);
301	  const settled = chargedAgainstCap(
302	    roundedInFavourOfMHPCO.disbursed(
303	      amountClaimed(claim.incident, policy.items),
304	    ),
305	    capBefore,
306	  );
307	
308	  capRemainingByPolicy.set(claim.policy, settled.remainingCap);
309	
310	  return settled;
311	};
312	
313	const priceQuote = (
314	  quote: QuoteStep,
315	  stepIndex: number,
316	  customer: Customer,
317	): QuoteResult => ({
318	  premium: quotePremium(quote.items, {
319	    customer,
320	    isFollowUpContract: hasPrecedingStep(stepIndex),
321	  }),
322	});
323	
324	/**
325	 * Steps are settled IN ORDER, and that order is load-bearing: a claim's payout
326	 * depends on how much of the policy's cap the claims before it consumed.
327	 */
328	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
329	  const capRemainingByPolicy = new Map<number, number>();
330	
331	  return {
332	    results: scenario.steps.map((step, stepIndex) =>
333	      isQuoteStep(step)
334	        ? priceQuote(step, stepIndex, scenario.customer)
335	        : settleClaim(step, scenario.steps, capRemainingByPolicy),
336	    ),
337	  };
338	};
